package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayV2HTTPEvent;
import com.eventpulse.util.ResponseUtil;
final class HandlerTestSupport {private HandlerTestSupport(){}static APIGatewayV2HTTPEvent event(String json){try{return ResponseUtil.JSON.readValue(json,APIGatewayV2HTTPEvent.class);}catch(Exception e){throw new IllegalArgumentException(e);}}static String request(String method,String path,String extra){return "{\"version\":\"2.0\",\"rawPath\":\""+path+"\",\"body\":null,\"headers\":{},\"requestContext\":{\"http\":{\"method\":\""+method+"\",\"path\":\""+path+"\"}"+extra+"}}";}static String withBearer(String request,String token){return request.replace("\"headers\":{}","\"headers\":{\"authorization\":\"Bearer "+token+"\"}");}static String claims(String sub,String group){return ",\"authorizer\":{\"jwt\":{\"claims\":{\"sub\":\""+sub+"\""+(group==null?"":",\"cognito:groups\":\"["+group+"]\"")+",\"email\":\""+sub+"@example.test\",\"name\":\"Test User\"}}}}";}}
